it('目录条件变化和撤权隔离迟到结果，原成员继续旧三字段读取且没有管理筛选',async()=>{
 let first!:(value:unknown)=>void,late!:(value:unknown)=>void
 const directory=vi.fn().mockImplementationOnce(()=>new Promise(done=>{first=done})).mockResolvedValue({items:[view({firmwareVersion:'当前条件'})],nextCursor:null,hasMore:false,total:'1'})
 const list=vi.fn().mockResolvedValue({items:[decodeOtaFirmware(value({firmwareVersion:'成员原读取'}),project)],nextCursor:null,hasMore:false})
 const wrapper=render(Versions,{...otaReadTransport,directory,list});await flushPromises()
 wrapper.findAllComponents(ElSelect).find(node=>node.props('modelValue')==='DESC')!.vm.$emit('update:modelValue','ASC');await flushPromises();expect(wrapper.text()).toContain('当前条件')
 first({items:[view({firmwareVersion:'旧条件迟到'})],nextCursor:null,hasMore:false,total:'99'});await flushPromises();expect(wrapper.text()).not.toContain('旧条件迟到');expect(wrapper.text()).not.toContain('共 99')
 directory.mockImplementationOnce(()=>new Promise(done=>{late=done}));wrapper.findAllComponents(ElSelect).find(node=>node.props('modelValue')==='ASC')!.vm.$emit('update:modelValue','DESC');await flushPromises()
 session.user={...session.user!,projectRole:'VIEWER',permissions:[]};session.projects=[{id:project,myRole:'VIEWER',status:'ARCHIVED'}];await flushPromises();expect(list).toHaveBeenCalledWith(project,undefined,expect.any(AbortSignal));expect(wrapper.findComponent(TaskChoiceSelect).exists()).toBe(false);expect(wrapper.text()).not.toContain('版本名称');expect(wrapper.text()).toContain('成员原读取');expect(wrapper.text()).not.toContain('共 1 个版本')
 late({items:[view({firmwareVersion:'撤权迟到'})],nextCursor:null,hasMore:false,total:'77'});await flushPromises();expect(wrapper.text()).not.toContain('撤权迟到');expect(wrapper.text()).not.toContain('共 77')
 session.user=null;await flushPromises();expect(wrapper.text()).not.toContain('成员原读取');expect(wrapper.text()).toContain('没有此内容的读取权限')
})
