it('签名发布在途禁止元数据刷新卸载子组件，上传完成回调仍能刷新',async()=>{
 const wrapper=render(Detail);await flushPromises();await click('读取管理元数据')
 const publication=wrapper.findComponent(Publication),original=publication.vm.$.uid
 expect(publication.exists()).toBe(true)
 // 使用真实子组件的锁事件验证宿主边界，不模拟签名服务资格。
 publication.vm.$emit('locked',true);await flushPromises()
 const before=state.api.mock.calls.length,locks=wrapper.emitted('locked')?.length
 expect(wrapper.emitted('locked')?.at(-1)).toEqual([true])
 expect(button('读取管理元数据').disabled).toBe(true)
 button('读取管理元数据').click()
 // 同时验证函数守卫，程序化重放click不依赖HTML disabled的阻拦。
 wrapper.findAllComponents(ElButton).find(node=>node.text()==='读取管理元数据')!.vm.$emit('click')
 await flushPromises()
 expect(state.api.mock.calls).toHaveLength(before)
 expect(wrapper.findComponent(Publication).vm.$.uid).toBe(original)
 expect(wrapper.emitted('locked')).toHaveLength(locks!)
 expect(wrapper.emitted('locked')?.at(-1)).toEqual([true])
 publication.vm.$emit('locked',false);await flushPromises()
 expect(button('读取管理元数据').disabled).toBe(false)
 const upload=wrapper.findComponent(Upload)
 upload.vm.$emit('locked',true);await flushPromises()
 upload.vm.$emit('changed');await flushPromises()
 expect(state.api.mock.calls.length).toBe(before+3)
 expect(wrapper.emitted('locked')?.at(-1)).toEqual([true])
 upload.vm.$emit('locked',false);await flushPromises()
 expect(wrapper.emitted('locked')?.at(-1)).toEqual([false])
 expect(state.api.mock.calls.every(([,options])=>!options?.method||options.method==='get')).toBe(true)
})

