it('旧V1统计说明原因允许真实C1，未知与确定零仍分开且当前版本保持未声明',async()=>{
 const fw=decodeOtaFirmware(value(),project),legacy=upgradeStatsValue({eligibilityReason:'LEGACY_EXECUTION_QUALIFICATION',currentUpgradeableCount:'1',allRelatedCount:'1',overallSuccessPercentage:'0.00'});expect(decodeOtaUpgradeStatistics(bytes(legacy),project,fw).currentUpgradeableCount).toBe('1');expect(()=>decodeOtaUpgradeStatistics(bytes({...legacy,eligibilityState:'UNAVAILABLE'}),project,fw)).toThrow();expect(()=>decodeOtaUpgradeStatistics(bytes({...legacy,eligibilityReason:'NON_READY_FIRMWARE'}),project,fw)).toThrow();expect(decodeOtaUpgradeStatistics(bytes(upgradeStatsValue({eligibilityState:'UNAVAILABLE',eligibilityReason:'TRUST_SOURCE_UNAVAILABLE',currentUpgradeableCount:null,allRelatedCount:null})),project,fw).currentUpgradeableCount).toBeNull()
 const row=upgradeDevice({currentEligible:true,relatedState:'NOT_DELIVERED',firstDeliveredAt:null,lastDeliveredAt:null,current:{...versionDevice(),version:null,alarm:{...versionDevice().alarm,observedAt:'2026-10-31T08:01:00Z'}}}),query={metric:'ALL_RELATED' as const,order:'LAST_DELIVERED_DESC' as const,page:1,limit:20};const page=decodeOtaUpgradeDevices(bytes(upgradeDevicesValue({eligibilityReason:'LEGACY_EXECUTION_QUALIFICATION',items:[row],total:'1'})),project,fw,query)
 const wrapper=renderUpgrade({read:vi.fn().mockResolvedValue(decodeOtaUpgradeStatistics(bytes(legacy),project,fw)),devices:vi.fn().mockResolvedValue(page)});await flushPromises();expect(wrapper.text()).toContain('按旧版固件的安全执行资格统计，未声明版本属性');expect(wrapper.text()).toContain('未声明版本属性');expect(wrapper.text()).toContain('当前符合升级条件');expect(wrapper.find('button[aria-label="当前可升级设备数"]').text()).toContain('1');expect(wrapper.text()).not.toContain('当前可升级范围和完成度尚未确认');expect(page.items[0]?.current?.version).toBeNull()
})
